Rules.InvariantScript:
Patch(
    'SES Chat', 
    Defaults('SES Chat'), 
    {

        Title: LookUp(Users, ID = currentUserID).Name,
        'Chat Message': InputChatMessage.Text, 
        'Chat Status': {Value: "Active"}
    }

);
Reset(InputChatMessage);
Notify("Message has been recorded")

Set(currentUserID, Blank());

Navigate(LoginScreen);

Notify(
    "You have been logged out.",
    NotificationType.Information
);
